#include "download_service.h"
#include <windows.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>

typedef struct{char*s;size_t n,cap;} DBuf;
static int db_add(DBuf*b,const char*s,size_t n){if(n>(size_t)-1-b->n-1)return 0;size_t need=b->n+n+1;if(need>b->cap){size_t c=b->cap?b->cap:2048;while(c<need){if(c>32u*1024u*1024u){c=need;break;}c*=2;}char*p=(char*)realloc(b->s,c);if(!p)return 0;b->s=p;b->cap=c;}memcpy(b->s+b->n,s,n);b->n+=n;b->s[b->n]=0;return 1;}
static int db_s(DBuf*b,const char*s){return s?db_add(b,s,strlen(s)):1;}
static int db_printf(DBuf*b,const char*format,...){va_list args,copy;va_start(args,format);va_copy(copy,args);int n=vsnprintf(NULL,0,format,copy);va_end(copy);if(n<0){va_end(args);return 0;}char*line=(char*)malloc((size_t)n+1);if(!line){va_end(args);return 0;}vsnprintf(line,(size_t)n+1,format,args);va_end(args);int ok=db_add(b,line,(size_t)n);free(line);return ok;}
static void copy_out(char*out,size_t cap,const char*s){if(out&&cap){snprintf(out,cap,"%s",s?s:"");out[cap-1]=0;}}
static wchar_t*to_wide(const char*s){int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,NULL,0);if(n<=0)return NULL;wchar_t*w=(wchar_t*)malloc((size_t)n*sizeof(*w));if(!w)return NULL;if(!MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,w,n)){free(w);return NULL;}return w;}
static int path_join(char*out,size_t cap,const char*a,const char*b){size_t n=strlen(a);while(n&&(a[n-1]=='\\'||a[n-1]=='/'))n--;int k=snprintf(out,cap,"%.*s\\%s",(int)n,a,b);return k>=0&&(size_t)k<cap;}
static int safe_write(const char*path,const char*text,size_t length,char*error,size_t error_cap){wchar_t*w=to_wide(path);if(!w){copy_out(error,error_cap,"Некоректний шлях або UTF-8.");return 0;}wchar_t tmp[ZD_PATH_MAX];int k=swprintf(tmp,ZD_PATH_MAX,L"%ls.%lu.%lu.tmp",w,(unsigned long)GetCurrentProcessId(),(unsigned long)GetTickCount());if(k<0||(size_t)k>=ZD_PATH_MAX){free(w);copy_out(error,error_cap,"Шлях до файла надто довгий.");return 0;}HANDLE h=CreateFileW(tmp,GENERIC_WRITE,0,NULL,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,NULL);if(h==INVALID_HANDLE_VALUE){free(w);copy_out(error,error_cap,"Не вдалося створити тимчасовий файл документа.");return 0;}BOOL ok=length<=0xffffffffu;DWORD wrote=0;if(ok)ok=WriteFile(h,text,(DWORD)length,&wrote,NULL)&&wrote==(DWORD)length&&FlushFileBuffers(h);CloseHandle(h);if(ok)ok=MoveFileExW(tmp,w,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);if(!ok){DeleteFileW(tmp);copy_out(error,error_cap,"Не вдалося атомарно зберегти файл документа.");}free(w);return ok?1:0;}
static int clean_url(const char*src,char*out,size_t cap){if(!src||!cap)return 0;while(*src==' '||*src=='\t'||*src=='\r'||*src=='\n')src++;size_t n=strlen(src);while(n&&(src[n-1]==' '||src[n-1]=='\t'||src[n-1]=='\r'||src[n-1]=='\n'))n--;const char*hash=(const char*)memchr(src,'#',n);if(hash)n=(size_t)(hash-src);if(n>=cap)return 0;memcpy(out,src,n);out[n]=0;return n>0;}
static void notify(ZDProgressCallback cb,void*ctx,int stage,const char*text){if(cb)cb(ctx,stage,text);}
static void finish_history(ZDSqliteApi*sqlite,const ZDPaths*paths,int64_t id,const char*status,const char*title,const char*file,const char*message){if(id<=0)return;char err[ZD_ERROR_MAX];if(!zd_history_finish(sqlite,paths->history_db,id,status,title,file,message,err,sizeof(err)))zd_log_write(paths,"ERROR","history","Не вдалося оновити запис #%lld: %s",(long long)id,err);}
static int build_document_text(const ZDDocument*d,const char*url,char**out,size_t*out_len){SYSTEMTIME t;GetLocalTime(&t);char downloaded[32];snprintf(downloaded,sizeof(downloaded),"%02u.%02u.%04u %02u:%02u",t.wDay,t.wMonth,t.wYear,t.wHour,t.wMinute);DBuf b={0};if(!db_printf(&b,"Назва:       %s\nТип:         %s\nНомер:       %s\nПрийнятий:   %s\nРедакція:    %s\nСтатус:      %s\nДжерело:     %s\nЗавантажено: %s\n",d->title,d->document_type[0]?d->document_type:"-",d->number[0]?d->number:"-",d->adoption_date[0]?d->adoption_date:"-",d->revision_date[0]?d->revision_date:"-",d->status[0]?d->status:"-",url,downloaded)){free(b.s);return 0;}for(int i=0;i<72;i++)if(!db_add(&b,"=",1)){free(b.s);return 0;}if(!db_s(&b,"\n\n")){free(b.s);return 0;}const char*content=d->content?d->content:"";while(*content==' '||*content=='\r'||*content=='\n'||*content=='\t')content++;size_t n=strlen(content);while(n&&(content[n-1]==' '||content[n-1]=='\r'||content[n-1]=='\n'||content[n-1]=='\t'))n--;if(!db_add(&b,content,n)||!db_s(&b,"\n")){free(b.s);return 0;}*out=b.s;*out_len=b.n;return 1;}
int zd_download_run(const char*input,const ZDSettings*settings,const ZDPaths*paths,ZDSqliteApi*sqlite,ZDProgressCallback progress,void*context,ZDDownloadResult*result){if(!result)return 0;memset(result,0,sizeof(*result));if(!settings||!paths||!sqlite){copy_out(result->error,sizeof(result->error),"Внутрішня помилка: не передано налаштування або сховище.");return 0;}if(!clean_url(input,result->url,sizeof(result->url))){copy_out(result->error,sizeof(result->error),"Введіть посилання на документ Верховної Ради України.");return 0;}char validation[ZD_ERROR_MAX];if(!zd_validate_url(result->url,validation,sizeof(validation))){copy_out(result->error,sizeof(result->error),validation);return 0;}
    char sql_error[ZD_ERROR_MAX];if(!zd_history_start(sqlite,paths->history_db,result->url,&result->history_id,sql_error,sizeof(sql_error))){copy_out(result->error,sizeof(result->error),sql_error);zd_log_write(paths,"ERROR","history","Не вдалося створити запис історії: %s",sql_error);return 0;}
    zd_log_write(paths,"INFO","download","Початок завантаження: %s",result->url);notify(progress,context,1,"Отримую сторінку документа…");ZDHttpSettings hs={settings->request_timeout_connect,settings->request_timeout_read,settings->max_retry_attempts};ZDHttpResult net;int ok=zd_http_fetch_document(result->url,&hs,&net);result->http_status=net.status_code;if(!ok){copy_out(result->error,sizeof(result->error),net.error[0]?net.error:"Не вдалося отримати сторінку документа.");finish_history(sqlite,paths,result->history_id,"Помилка",NULL,NULL,result->error);zd_log_write(paths,"ERROR","download","HTTP %d: %s",net.status_code,result->error);zd_http_result_free(&net);return 0;}
    notify(progress,context,2,"Перевіряю текст і метадані…");ZDDocument doc;char parse_error[ZD_ERROR_MAX];if(!zd_parse_html(net.html,&doc,parse_error,sizeof(parse_error))){copy_out(result->error,sizeof(result->error),parse_error);finish_history(sqlite,paths,result->history_id,"Пропущено",NULL,NULL,result->error);zd_log_write(paths,"WARNING","parser","Документ пропущено: %s | %s",result->url,result->error);zd_http_result_free(&net);return 0;}zd_http_result_free(&net);
    copy_out(result->title,sizeof(result->title),doc.title);const char*directory=settings->documents_dir[0]?settings->documents_dir:paths->documents;if(!zd_ensure_directory_utf8(directory)){copy_out(result->error,sizeof(result->error),"Не вдалося створити папку для документів.");finish_history(sqlite,paths,result->history_id,"Помилка",doc.title,NULL,result->error);zd_log_write(paths,"ERROR","document","%s",result->error);zd_free_document(&doc);return 0;}
    char filename[256];if(!zd_build_filename(doc.title,doc.revision_date,filename,sizeof(filename))||!path_join(result->saved_path,sizeof(result->saved_path),directory,filename)){copy_out(result->error,sizeof(result->error),"Не вдалося сформувати ім'я файла або шлях надто довгий.");finish_history(sqlite,paths,result->history_id,"Помилка",doc.title,NULL,result->error);zd_free_document(&doc);return 0;}
    notify(progress,context,3,"Формую й зберігаю текстовий файл…");char*text=NULL;size_t length=0;if(!build_document_text(&doc,result->url,&text,&length)){copy_out(result->error,sizeof(result->error),"Недостатньо пам'яті для формування документа.");finish_history(sqlite,paths,result->history_id,"Помилка",doc.title,NULL,result->error);zd_free_document(&doc);return 0;}if(!safe_write(result->saved_path,text,length,result->error,sizeof(result->error))){finish_history(sqlite,paths,result->history_id,"Помилка",doc.title,NULL,result->error);zd_log_write(paths,"ERROR","document","%s",result->error);free(text);zd_free_document(&doc);return 0;}
    free(text);finish_history(sqlite,paths,result->history_id,"Успішно",doc.title,result->saved_path,NULL);result->success=1;zd_log_write(paths,"INFO","download","Успішно: %s | %s",doc.title,result->saved_path);notify(progress,context,4,"Готово — документ збережено.");zd_free_document(&doc);return 1;}
